#!/usr/bin/env python3
import base64,zlib,json,hashlib,os,socket,shutil,tempfile,fcntl
from pathlib import Path
from datetime import datetime,timezone
BUNDLE=''
def sha(b):return hashlib.sha256(b).hexdigest()
def apply(root,backup_base,host_check=True):
 if host_check:
  assert socket.gethostname()=='vdska' and os.geteuid()==0,'STOP: wrong host/user'
 assert root.is_dir() and not root.is_symlink(),'STOP: root'
 lock=open('/tmp/azmednsk-portraits-v1.lock','a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 p=json.loads(zlib.decompress(base64.b64decode(BUNDLE)))
 def target(rel):
  relp=Path(rel);assert not relp.is_absolute() and '..' not in relp.parts
  dest=root/relp
  assert all(not q.is_symlink() for q in [dest,*dest.parents] if q!=root.parent),'STOP: symlink'
  assert dest.resolve().is_relative_to(root.resolve())
  return dest
 guards={}
 for rel in ['team/index.html','team-2/index.html']:
  dest=target(rel);assert dest.is_file(), 'STOP: missing team';guards[rel]=dest.read_bytes()
 assert sha(guards['team/index.html'])=='93a5390b094522f7cea38048b12a714a2b42da9b4406741dacc24c6250073655','STOP: approved team changed'
 changes=p['changes'];assets={k:base64.b64decode(v['data']) for k,v in p['assets'].items()}
 assert all(sha(b)==p['assets'][k]['sha'] for k,b in assets.items()),'STOP: payload asset'
 assert not any(k in changes for k in guards)
 if all(target(k).is_file() and sha(target(k).read_bytes())==v['after'] for k,v in changes.items()) and all(target(k).is_file() and target(k).read_bytes()==v for k,v in assets.items()):
  print('PORTRAITS_ALREADY_APPLIED=PASS');return
 before={}
 for rel,item in changes.items():
  dest=target(rel);assert dest.is_file(),'STOP: missing '+rel
  before[rel]=dest.read_bytes();assert sha(before[rel])==item['before'],'STOP: page changed '+rel
  assert sha(item['content'].encode())==item['after'],'STOP: payload page'
 for rel,data in assets.items():
  dest=target(rel);assert not dest.exists() or dest.read_bytes()==data,'STOP: asset collision'
 print('PREFLIGHT=PASS; PAGES=64; PORTRAITS=101; IDENTITIES=11',flush=True)
 backup=backup_base/('portraits-per-load-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'));backup.mkdir(parents=True)
 for rel,data in {**before,**guards}.items():
  d=backup/rel;d.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(target(rel),d);assert d.read_bytes()==data
 (backup/'manifest.json').write_text(json.dumps({k:{'before':v['before'],'after':v['after']} for k,v in changes.items()},indent=2))
 def atomic(dest,data,original=False):
  fd,tmp=tempfile.mkstemp(prefix='.az-portrait-',dir=dest.parent)
  try:
   with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
   if original:
    shutil.copystat(dest,tmp);st=dest.stat();os.chown(tmp,st.st_uid,st.st_gid)
   else:os.chmod(tmp,0o644)
   os.replace(tmp,dest)
  finally:
   if os.path.exists(tmp):os.unlink(tmp)
 changed=[];created=[]
 try:
  for rel,data in assets.items():
   dest=target(rel)
   if not dest.exists():dest.parent.mkdir(parents=True,exist_ok=True);atomic(dest,data);created.append(rel)
  for rel,item in changes.items():
   dest=target(rel);assert dest.read_bytes()==before[rel],'STOP: concurrent edit '+rel
   atomic(dest,item['content'].encode(),True);changed.append(rel)
  assert all(sha(target(k).read_bytes())==v['after'] for k,v in changes.items())
  assert all(target(k).read_bytes()==v for k,v in assets.items())
  assert all(target(k).read_bytes()==v for k,v in guards.items()),'STOP: team changed concurrently'
 except BaseException:
  for rel in reversed(changed):
   if sha(target(rel).read_bytes())==changes[rel]['after']:atomic(target(rel),before[rel],True)
  # Retain new assets if another writer might already reference them.
  print('ROLLBACK=ATTEMPTED; BACKUP='+str(backup));raise
 print('SITE_PORTRAITS=PASS; RANDOM_PER_LOAD=YES; AUTOPLAY=NONE; ARROWS=NONE; TEAM_AND_PREVIEW=UNCHANGED')
 print('BACKUP='+str(backup));print('URL=https://azmednsk.ru/team/zubachev-roman/')
if __name__=='__main__':
 try:apply(Path('/var/www/azmednsk-preview'),Path('/var/backups/azmednsk'))
 except Exception as e:raise SystemExit(str(e))
